WITH lines AS (SELECT id, service, level, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, v) SELECT id, service, latency_ms, status_code, attr_key, v, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY status_code ASC, id ASC, attr_key ASC) AS row_seq, AVG(latency_ms) OVER (PARTITION BY attr_key) AS attr_key_avg_latency_ms, RANK() OVER w_hist AS latency_ms_rank FROM lines WHERE latency_ms > 1231 WINDOW w_hist AS (PARTITION BY service, level ORDER BY latency_ms DESC NULLS LAST);
